/*
 * Runtime contract for ARMv7 code generated by vitarecomp (arm/emit.py).
 * Build generated code with: -fwrapv -fno-strict-aliasing -ffp-contract=off -fno-math-errno
 */
#ifndef ARC_H
#define ARC_H
#include <stdint.h>

typedef struct arc_ctx {
  uint32_t r[16];
  uint32_t n, z, c, v; /* APSR flags as 0/1 */
  uint64_t d[32];      /* VFP/NEON D registers; S(2k) = low half of D(k), S(2k+1) = high half */
  uint32_t fpscr;
  uint32_t tpidruro;
  uint32_t tpidrurw;   /* TLS de usuário gravável (mcr/mrc p15,0,rX,c13,c0,2) */
  uint32_t apsr_rest; /* APSR bits other than NZCV (Q, GE); Q is not yet modelled */
} arc_ctx;

typedef void (*arc_func)(arc_ctx *);
typedef struct {
  uint32_t key; /* entry address | Thumb bit */
  arc_func fn;
  const char *name;
} arc_func_entry;
typedef struct {
  uint32_t vaddr, filesz, memsz;
  const uint8_t *data;
} arc_segment;

extern uint8_t *arc_mem;
extern const arc_func_entry arc_func_table[];
extern const unsigned arc_func_count;
extern const arc_segment arc_segments[];
extern const unsigned arc_segment_count;
extern const uint32_t arc_entry;

/* ---- guest memory: flat 4 GiB window, unaligned-safe little-endian accesses ---- */
#define ARC_P(a) (arc_mem + (uint32_t)(a))
static inline uint32_t ARC_LW(uint32_t a) { uint32_t v; __builtin_memcpy(&v, ARC_P(a), 4); return v; }
static inline uint32_t ARC_LHU(uint32_t a) { uint16_t v; __builtin_memcpy(&v, ARC_P(a), 2); return v; }
static inline uint32_t ARC_LH(uint32_t a) { int16_t v; __builtin_memcpy(&v, ARC_P(a), 2); return (uint32_t)(int32_t)v; }
static inline uint32_t ARC_LBU(uint32_t a) { return *ARC_P(a); }
static inline uint32_t ARC_LB(uint32_t a) { return (uint32_t)(int32_t)(int8_t)*ARC_P(a); }
static inline void ARC_SW(uint32_t a, uint32_t v) { __builtin_memcpy(ARC_P(a), &v, 4); }
static inline void ARC_SH(uint32_t a, uint32_t v) { uint16_t h = (uint16_t)v; __builtin_memcpy(ARC_P(a), &h, 2); }
static inline void ARC_SB(uint32_t a, uint32_t v) { *ARC_P(a) = (uint8_t)v; }

/* ---- integer helpers ---- */
#define ARC_ROR(x, s) ((s) & 31 ? (((x) >> ((s) & 31)) | ((x) << (32 - ((s) & 31)))) : (x))
#define ARC_CLZ(x) ((x) ? (uint32_t)__builtin_clz(x) : 32u)
static inline uint32_t arc_rbit(uint32_t x) {
  x = ((x >> 1) & 0x55555555u) | ((x & 0x55555555u) << 1);
  x = ((x >> 2) & 0x33333333u) | ((x & 0x33333333u) << 2);
  x = ((x >> 4) & 0x0f0f0f0fu) | ((x & 0x0f0f0f0fu) << 4);
  return __builtin_bswap32(x);
}
/* Register-specified shifts: amount = Rs[7:0]. */
static inline uint32_t ARC_SHIFT_LSL(uint32_t x, uint32_t s) { s &= 0xff; return s >= 32 ? 0 : x << s; }
static inline uint32_t ARC_SHIFT_LSR(uint32_t x, uint32_t s) { s &= 0xff; return s >= 32 ? 0 : x >> s; }
static inline uint32_t ARC_SHIFT_ASR(uint32_t x, uint32_t s) { s &= 0xff; return (uint32_t)((int32_t)x >> (s >= 32 ? 31 : s)); }
static inline uint32_t ARC_SHIFT_ROR(uint32_t x, uint32_t s) { return ARC_ROR(x, s & 31); }
#define ARC_SHIFT_C_LSL(x, s, c) ARC_SHIFT_LSL(x, s)
#define ARC_SHIFT_C_LSR(x, s, c) ARC_SHIFT_LSR(x, s)
#define ARC_SHIFT_C_ASR(x, s, c) ARC_SHIFT_ASR(x, s)
#define ARC_SHIFT_C_ROR(x, s, c) ARC_SHIFT_ROR(x, s)
static inline uint32_t ARC_SHIFT_CO_LSL(uint32_t x, uint32_t s, uint32_t c) {
  s &= 0xff; return s == 0 ? c : s < 32 ? (x >> (32 - s)) & 1 : s == 32 ? x & 1 : 0;
}
static inline uint32_t ARC_SHIFT_CO_LSR(uint32_t x, uint32_t s, uint32_t c) {
  s &= 0xff; return s == 0 ? c : s < 32 ? (x >> (s - 1)) & 1 : s == 32 ? x >> 31 : 0;
}
static inline uint32_t ARC_SHIFT_CO_ASR(uint32_t x, uint32_t s, uint32_t c) {
  s &= 0xff; return s == 0 ? c : s < 32 ? (x >> (s - 1)) & 1 : x >> 31;
}
static inline uint32_t ARC_SHIFT_CO_ROR(uint32_t x, uint32_t s, uint32_t c) {
  s &= 0xff; return s == 0 ? c : (ARC_ROR(x, s & 31)) >> 31;
}
static inline uint32_t ARC_SDIV(uint32_t a, uint32_t b) {
  if (b == 0) return 0;
  if (a == 0x80000000u && b == 0xffffffffu) return a;
  return (uint32_t)((int32_t)a / (int32_t)b);
}
static inline uint32_t ARC_UDIV(uint32_t a, uint32_t b) { return b ? a / b : 0; }
static inline uint32_t arc_usat(uint32_t x, int n) {
  int32_t v = (int32_t)x, hi = (int32_t)((1u << n) - 1);
  return (uint32_t)(v < 0 ? 0 : v > hi ? hi : v);
}
static inline uint32_t arc_ssat(uint32_t x, int n) {
  int32_t v = (int32_t)x, hi = (int32_t)((1u << (n - 1)) - 1), lo = -hi - 1;
  return (uint32_t)(v < lo ? lo : v > hi ? hi : v);
}

/* ---- VFP ---- */
static inline uint32_t ARC_GSB(arc_ctx *c, int n) { return (uint32_t)(c->d[n >> 1] >> (32 * (n & 1))); }
static inline void ARC_SSB(arc_ctx *c, int n, uint32_t v) {
  int sh = 32 * (n & 1);
  c->d[n >> 1] = (c->d[n >> 1] & ~(0xffffffffull << sh)) | ((uint64_t)v << sh);
}
static inline float arc_bitsf(uint32_t b) { float f; __builtin_memcpy(&f, &b, 4); return f; }
static inline uint32_t arc_fbits(float f) { uint32_t b; __builtin_memcpy(&b, &f, 4); return b; }
static inline double arc_bitsd(uint64_t b) { double d; __builtin_memcpy(&d, &b, 8); return d; }
static inline uint64_t arc_dbits(double d) { uint64_t b; __builtin_memcpy(&b, &d, 8); return b; }
static inline float ARC_GS(arc_ctx *c, int n) { return arc_bitsf(ARC_GSB(c, n)); }
static inline void ARC_SS(arc_ctx *c, int n, float v) { ARC_SSB(c, n, arc_fbits(v)); }
static inline double ARC_GD(arc_ctx *c, int n) { return arc_bitsd(c->d[n]); }
static inline void ARC_SD(arc_ctx *c, int n, double v) { c->d[n] = arc_dbits(v); }

/* ARM NaN rules (FPSCR.DN = 0): an sNaN operand wins (quieted), else the first
 * qNaN operand; a NaN generated by the operation is the default NaN 0x7fc00000. */
float arc_nan_s(float a, float b, int nargs);
double arc_nan_d(double a, double b, int nargs);
#define ARC_FIX_S2(r, a, b) (__builtin_expect((r) == (r), 1) ? (r) : arc_nan_s((a), (b), 2))
#define ARC_FIX_D2(r, a, b) (__builtin_expect((r) == (r), 1) ? (r) : arc_nan_d((a), (b), 2))
#define ARC_FIX_S1(r, a) (__builtin_expect((r) == (r), 1) ? (r) : arc_nan_s((a), (a), 1))
#define ARC_FIX_D1(r, a) (__builtin_expect((r) == (r), 1) ? (r) : arc_nan_d((a), (a), 1))
double arc_cvt_d_s(float a);
float arc_cvt_s_d(double a);
uint32_t arc_f2s32(double v, unsigned rmode);
uint32_t arc_f2u32(double v, unsigned rmode);
uint32_t arc_f2s16(double v, unsigned rmode); /* result sign-extended to 32 bits */
uint32_t arc_f2u16(double v, unsigned rmode);
uint32_t arc_vcmp_flags(double a, double b);
/* VCVTB/VCVTT: meia precisão <-> simples, com FPSCR (AHP bit 26, DN 25, FZ 24, RMode 23:22). */
uint32_t arc_f16_to_f32(uint32_t h, uint32_t fpscr);
uint32_t arc_f32_to_f16(uint32_t f, uint32_t fpscr);

/* ---- NEON ---- */
static inline uint32_t ARC_L8(uint32_t a) { return ARC_LBU(a); }
static inline uint32_t ARC_L16(uint32_t a) { return ARC_LHU(a); }
static inline uint32_t ARC_L32(uint32_t a) { return ARC_LW(a); }
static inline uint64_t ARC_L64(uint32_t a) { uint64_t v; __builtin_memcpy(&v, ARC_P(a), 8); return v; }
static inline void ARC_S8(uint32_t a, uint32_t v) { ARC_SB(a, v); }
static inline void ARC_S16(uint32_t a, uint32_t v) { ARC_SH(a, v); }
static inline void ARC_S32(uint32_t a, uint32_t v) { ARC_SW(a, v); }
static inline void ARC_S64(uint32_t a, uint64_t v) { __builtin_memcpy(ARC_P(a), &v, 8); }
/* "Standard FPSCR" semantics used by every NEON float op: flush-to-zero + default NaN. */
static inline float arc_nftz(float x) {
  uint32_t b = arc_fbits(x);
  return (b & 0x7f800000u) == 0 ? arc_bitsf(b & 0x80000000u) : x;
}
static inline float arc_nfix(float r) {
  if (r != r) return arc_bitsf(0x7fc00000u);
  return arc_nftz(r);
}
static inline float arc_nmax(float a, float b) {
  if (a != a || b != b) return arc_bitsf(0x7fc00000u);
  if (a == 0 && b == 0) return arc_bitsf(arc_fbits(a) & arc_fbits(b)); /* +0 wins */
  return a > b ? a : b;
}
static inline float arc_nmin(float a, float b) {
  if (a != a || b != b) return arc_bitsf(0x7fc00000u);
  if (a == 0 && b == 0) return arc_bitsf(arc_fbits(a) | arc_fbits(b)); /* -0 wins */
  return a < b ? a : b;
}
float arc_recpe(float x);
float arc_rsqrte(float x);
uint32_t arc_recpe_u32(uint32_t x);
uint32_t arc_rsqrte_u32(uint32_t x);
float arc_recps(float a, float b);
float arc_rsqrts(float a, float b);
static inline __int128 arc_sat_s(__int128 v, long long lo, long long hi) { return v < lo ? lo : v > hi ? hi : v; }
static inline __int128 arc_sat_u(__int128 v, unsigned long long hi) { return v < 0 ? 0 : v > (__int128)hi ? (__int128)hi : v; }
static inline uint32_t arc_cls(int32_t x, int n) {
  int32_t v = (int32_t)((uint32_t)x << (32 - n)) >> (32 - n);
  uint32_t t = (uint32_t)(v ^ (v >> 31));
  return t == 0 ? (uint32_t)(n - 1) : (uint32_t)(__builtin_clz(t) - (32 - n) - 1);
}
/* VSHL/VRSHL/VQSHL/VQRSHL by a signed per-lane register amount. */
uint64_t arc_nshl(uint64_t x, int8_t sh, int n, int is_signed, int rounding, int saturating);

/* ---- services ---- */
void arc_dispatch(arc_ctx *ctx, uint32_t target, uint32_t from);
/* Um chamado voltou para ctx->r[15] != `expected` (longjmp do guest, troca de contexto): o runtime
 * precisa desempilhar o C e continuar em r[15]. Cada plataforma decide como (fatal nos testes). */
__attribute__((noreturn)) void arc_ret_mismatch(arc_ctx *ctx, uint32_t expected);
void arc_svc(arc_ctx *ctx, uint32_t imm, uint32_t pc);
void arc_import(arc_ctx *ctx, uint32_t nid, uint32_t pc);
__attribute__((noreturn)) void arc_trap(arc_ctx *ctx, uint32_t pc);
__attribute__((noreturn)) void arc_unimpl(arc_ctx *ctx, uint32_t pc);
int arc_run(void);
void arc_trace_insn(arc_ctx *ctx, uint32_t pc);
/* Optional initial register state (lockstep): returns nonzero if provided. */
int arc_platform_initial_state(arc_ctx *ctx);

/* ---- platform layer ---- */
void *arc_platform_reserve_4g(void);
long arc_platform_write(int fd, const void *buf, uint32_t len);
__attribute__((noreturn)) void arc_platform_exit(int code);
void arc_platform_log(const char *msg);
#endif
